package com.tekwatt.admin.service;import com.tekwatt.admin.dto.*;import com.tekwatt.admin.entity.*;import com.tekwatt.admin.repository.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service @Transactional public class GovernanceService{private final RolePolicyRepository roles;private final AdministratorRepository admins;private final AdminApiKeyRepository keys;private final PlatformSettingRepository settings;private final SecureRandom random=new SecureRandom();public GovernanceService(RolePolicyRepository r,AdministratorRepository a,AdminApiKeyRepository k,PlatformSettingRepository s){roles=r;admins=a;keys=k;settings=s;}public RolePolicy role(UUID tenant,RolePolicyRequest r){RolePolicy p=roles.findByTenantIdAndRoleNameIgnoreCase(tenant,r.roleName()).orElseGet(()->new RolePolicy(tenant,r.roleName()));p.update(r.permissions());return roles.save(p);}@Transactional(readOnly=true)public List<RolePolicy>roles(UUID t){return roles.findAllByTenantIdOrderByRoleName(t);}public Administrator admin(UUID tenant,UUID id,AdministratorRequest r){Administrator a=id==null?new Administrator(tenant,r.authUserId(),r.name(),r.email(),r.phone(),r.roleName()):admins.findById(id).orElseThrow(()->notFound("Administrator"));if(id!=null)a.update(r.name(),r.email(),r.phone(),r.roleName(),r.status()==null?"ACTIVE":r.status());return admins.save(a);}@Transactional(readOnly=true)public List<Administrator>admins(UUID t){return admins.findAllByTenantIdOrderByCreatedAtDesc(t);}public void deleteAdmin(UUID id){admins.deleteById(id);}public ApiKeyResponse createKey(UUID tenant,ApiKeyRequest r){byte[]b=new byte[32];random.nextBytes(b);String secret=Base64.getUrlEncoder().withoutPadding().encodeToString(b);String keyId="tw_"+UUID.randomUUID().toString().replace("-","").substring(0,20);AdminApiKey k=keys.save(new AdminApiKey(tenant,keyId,hash(secret),r.name(),r.roleName(),r.scopes()));return ApiKeyResponse.from(k,secret);}@Transactional(readOnly=true)public List<ApiKeyResponse>keys(UUID t){return keys.findAllByTenantIdOrderByCreatedAtDesc(t).stream().map(k->ApiKeyResponse.from(k,null)).toList();}public ApiKeyResponse disableKey(UUID id){AdminApiKey k=keys.findById(id).orElseThrow(()->notFound("API key"));k.disable();return ApiKeyResponse.from(k,null);}public Map<String,String>saveSettings(UUID tenant,Map<String,String>values){values.forEach((k,v)->{PlatformSetting s=settings.findByTenantIdAndSettingKey(tenant,k).orElseGet(()->new PlatformSetting(tenant,k));s.value(v);settings.save(s);});return getSettings(tenant);}@Transactional(readOnly=true)public Map<String,String>getSettings(UUID t){Map<String,String>m=new TreeMap<>();settings.findAllByTenantId(t).forEach(s->m.put(s.getSettingKey(),s.getSettingValue()));return m;}private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private ResponseStatusException notFound(String n){return new ResponseStatusException(HttpStatus.NOT_FOUND,n+" not found");}}
